function EventsCarousel() {
  const [index, setIndex] = useState(0);
  const total = EVENTS.length;

  function prev() {
    setIndex((i) => (i - 1 + total) % total);
  }
  function next() {
    setIndex((i) => (i + 1) % total);
  }

  return (
    <section id="events" className="border-y border-gold/20 bg-white/60 px-6 py-16">
      <div className="mx-auto max-w-5xl">
        <div className="mb-10 text-center">
          <p className="font-body text-xs font-semibold uppercase tracking-[0.25em] text-ph-blue">
            What We Do
          </p>
          <h2 className="mt-2 font-display text-3xl font-semibold tracking-tight text-ink">
            Our Activities
          </h2>
        </div>

        <div className="relative overflow-hidden rounded-2xl">
          <div
            className="flex transition-transform duration-500 ease-out"
            style={{ transform: `translateX(-${index * 100}%)` }}
          >
            {EVENTS.map((event) => (
              <div key={event.title} className="w-full flex-shrink-0">
                <div className="grid overflow-hidden rounded-2xl border border-gold/30 bg-white shadow-sm sm:grid-cols-2">
                  <img
                    src={event.image}
                    alt={event.title}
                    className="h-56 w-full object-cover sm:h-full"
                  />
                  <div className="flex flex-col justify-center p-6 sm:p-8">
                    <span className="inline-flex w-fit rounded-full bg-ph-blue/10 px-3 py-1 font-body text-xs font-semibold uppercase tracking-wide text-ph-blue">
                      {event.date}
                    </span>
                    <h3 className="mt-3 font-display text-xl font-semibold text-ink">
                      {event.title}
                    </h3>
                    <p className="mt-3 font-body text-sm leading-relaxed text-body">
                      {event.description}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>

          <button
            onClick={prev}
            className="absolute left-3 top-1/2 -translate-y-1/2 rounded-full border border-gold/40 bg-cream p-2 text-ph-blue shadow transition hover:bg-gold-soft/50"
            aria-label="Previous event"
          >
            <ChevronLeft size={20} />
          </button>
          <button
            onClick={next}
            className="absolute right-3 top-1/2 -translate-y-1/2 rounded-full border border-gold/40 bg-cream p-2 text-ph-blue shadow transition hover:bg-gold-soft/50"
            aria-label="Next event"
          >
            <ChevronRight size={20} />
          </button>
        </div>

        <div className="mt-6 flex justify-center gap-2">
          {EVENTS.map((_, i) => (
            <button
              key={i}
              onClick={() => setIndex(i)}
              className={`h-2 rounded-full transition-all ${
                i === index ? "w-6 bg-ph-blue" : "w-2 bg-gold/30"
              }`}
              aria-label={`Go to event ${i + 1}`}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

function AuthModal({ mode, onClose, onSwitchMode }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(false);

  useEffect(() => {
    function handleKey(e) {
      if (e.key === "Escape") onClose();
    }
    if (mode) document.addEventListener("keydown", handleKey);
    return () => document.removeEventListener("keydown", handleKey);
  }, [mode, onClose]);

  if (!mode) return null;
  const isLogin = mode === "login";

  function handleSubmit(e) {
    e.preventDefault();
    // wire this up to your real auth call
    console.log({ mode, email, password, rememberMe });
    onClose();
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-ink/60 p-4 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="relative w-full max-w-sm rounded-2xl border border-gold/30 bg-white p-6 shadow-xl sm:p-8"
      >
        <button
          onClick={onClose}
          className="absolute right-4 top-4 rounded-full p-1 text-body transition hover:bg-cream hover:text-ink"
          aria-label="Close"
        >
          <X size={18} />
        </button>

        <div className="mb-6 flex items-center gap-3">
          <img
            src={LOGO_SRC}
            alt=""
            className="h-10 w-10 rounded-full object-cover ring-2 ring-gold"
          />
          <h2 className="font-display text-lg font-semibold text-ink">
            {isLogin ? "Log in" : "Register"}
          </h2>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4 font-body">
          <div>
            <label className="mb-1 block text-sm font-medium text-ink">Email</label>
            <input
              type="email"
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="you@organization.org"
              className="w-full rounded-lg border border-ink/15 px-3 py-2 text-sm text-ink outline-none transition focus:border-ph-blue focus:ring-2 focus:ring-ph-blue/10"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium text-ink">Password</label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              className="w-full rounded-lg border border-ink/15 px-3 py-2 text-sm text-ink outline-none transition focus:border-ph-blue focus:ring-2 focus:ring-ph-blue/10"
            />
          </div>

          <label className="flex items-center gap-2 text-sm text-body">
            <input
              type="checkbox"
              checked={rememberMe}
              onChange={(e) => setRememberMe(e.target.checked)}
              className="h-4 w-4 rounded border-ink/20 text-ph-blue focus:ring-ph-blue"
            />
            Remember me
          </label>

          <button
            type="submit"
            className="w-full rounded-full bg-ph-blue py-2.5 text-sm font-semibold text-cream transition hover:bg-ph-blue/90"
          >
            {isLogin ? "Log in" : "Register"}
          </button>
        </form>

        <p className="mt-5 text-center font-body text-sm text-body">
          {isLogin ? "Don't have an account? " : "Already have an account? "}
          <button
            type="button"
            onClick={() => onSwitchMode(isLogin ? "register" : "login")}
            className="font-semibold text-ph-blue hover:text-ph-blue/80"
          >
            {isLogin ? "Register" : "Log in"}
          </button>
        </p>
      </div>
    </div>
  );
}

